/// Classifies the safety of food based on the number of days passed since a reference day.
/// 
/// # Parameters
/// - `x`: non-negative threshold in days for "safe" classification.
/// - `a`: reference day.
/// - `b`: evaluation day.
/// 
/// # Returns
/// - `"delicious"` if (b - a) <= 0.
/// - `"safe"`      if 0 < (b - a) <= x.
/// - `"dangerous"` if (b - a) > x.
fn determine_food_safety(x: i8, a: i8, b: i8) -> &'static str {
    let days_past = b - a;
    if days_past <= 0 {
        "delicious"
    } else if days_past <= x {
        "safe"
    } else {
        "dangerous"
    }
}

